<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Http\Request;use Illuminate\Support\Str;
class ContentController extends Controller {
 private array $map=['products'=>\App\Models\Product::class,'events'=>\App\Models\Event::class,'portfolios'=>\App\Models\Portfolio::class,'testimonials'=>\App\Models\Testimonial::class];
 private function model($type){abort_unless(isset($this->map[$type]),404);return $this->map[$type];}
 public function index($type){$model=$this->model($type);$rows=$model::latest()->paginate(15);return view('admin.content-index',compact('type','rows'));}
 public function create($type){$this->model($type);return view('admin.content-form',['type'=>$type,'row'=>null,'pillars'=>\App\Models\Pillar::all()]);}
 public function edit($type,$id){$model=$this->model($type);return view('admin.content-form',['type'=>$type,'row'=>$model::findOrFail($id),'pillars'=>\App\Models\Pillar::all()]);}
 public function save(Request $r,$type,$id=null){$model=$this->model($type);$rules=match($type){'products'=>['pillar_id'=>'required|exists:pillars,id','name'=>'required|max:180','description'=>'required','price'=>'nullable|numeric','price_type'=>'required|in:tetap,mulai_dari,negosiasi','stock'=>'nullable|integer|min:0','is_active'=>'nullable|boolean','is_featured'=>'nullable|boolean','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048'],'events'=>['pillar_id'=>'required|exists:pillars,id','title'=>'required|max:180','type'=>'required|in:bootcamp,seminar','description'=>'required','start_at'=>'required|date','location'=>'required|max:200','quota'=>'required|integer|min:1','fee'=>'required|numeric|min:0','status'=>'required|in:draft,buka,penuh,selesai','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048'],'portfolios'=>['title'=>'required|max:180','description'=>'required','client_name'=>'required|max:180','project_url'=>'nullable|url','image'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048'],'testimonials'=>['name'=>'required|max:180','content'=>'required','rating'=>'required|integer|between:1,5','is_published'=>'nullable|boolean']};$d=$r->validate($rules);if(in_array($type,['products','events'])&&!empty($d['name']??$d['title']))$d['slug']=Str::slug($d['name']??$d['title']).'-'.Str::random(5);if($r->hasFile('image'))$d['image']=$r->file('image')->store('content','public');foreach(['is_active','is_featured','is_published'] as $b)if(isset($rules[$b]))$d[$b]=$r->boolean($b);if($id)$model::findOrFail($id)->update($d);else $model::create($d);return redirect()->route('admin.content.index',$type)->with('success','Data berhasil disimpan.');}
 public function destroy($type,$id){$model=$this->model($type);$model::findOrFail($id)->delete();return back()->with('success','Data dihapus.');}
}
